INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11411, 36677, 'tt0091981', NULL, 'Solarbabies', 'Solarbabies', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/vKNdxHrWTmG80WXdmLWM6YddZvP.jpg', 'https://image.tmdb.org/t/p/original/oFUDnSUG8nPZ3V3yr21kQp3colL.jpg', 'In a future in which most water has disappeared from the Earth, we find a group of children, mostly teenagers, who are living at an orphanage, run by the despotic rulers of the new Earth. The group in question plays a hockey based game on roller skates and is quite good. It has given them a unity that transcends the attempts to bring them to heel by the government. Finding an orb of special power, they find it has unusual effects on them. They escape from the orphanage (on skates) and try to cross the wasteland looking for a place they can live free as the storm-troopers search for them and the orb.', NULL, NULL, 2.0843, 5.3, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
