INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11426, NULL, NULL, 1384, 'Hotline Miami', 'Hotline Miami', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vqp.jpg', NULL, 'A top-down slasher/shooter with unlockable gameplay-altering masks and weapons, featuring a neon-flavoured electronic aesthetic, in which a hitman receives anonymous calls ordering him to travel to certain residences and crime dens and massacre those within, as he stumbles through unreal visions and inconsistencies without any answers to how, why or who.', 'https://www.igdb.com/games/hotline-miami', '["Google Stadia", "Xbox Series X|S", "PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 8.20999999999999907e+00, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11427, 2636, 'tt0111255', NULL, 'The Specialist', 'The Specialist', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/9CVAjtkSaFs9FyddGfThj11ZuQq.jpg', 'https://image.tmdb.org/t/p/original/fvBshQMwOnYZdUXySGMdT6LiqsI.jpg', 'May Munro is a woman obsessed with getting revenge on the people who murdered her parents when she was still a girl. She hires Ray Quick, a retired explosives expert, to kill her parents'' killers. When Ned Trent, embittered ex-partner of Quick''s, is assigned to protect one of Quick''s potential victims, a deadly game of cat and mouse ensues.', NULL, NULL, 8.1668, 5.952, 0, 7.81000000000000049e+00, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
