INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11450, 1192050, 'tt3101522', NULL, 'Time Slip Megane', 'たいむすりっぷメガネ', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/o9sY58ZC5ua3QYJ30yJ0BvT36JW.jpg', NULL, 'Fuiko Hashida (Shinozaki) runs her own nail salon in Tokyo. She is informed of her father''s death one day. She has not spoken to her father in eight years and since leaving the hometown and falling out with him. She returns to town for the funeral. She is coincidentally wearing eyeglasses and travels eight years into the past and sees the town as if it were then. She remembers that at that time the town had trouble with a business and businessman dumping trash and destroying nature. She resolves to change the city''s future.', NULL, NULL, 0.998, 0.0, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11451, 1510325, 'tt36454256', NULL, 'Sweetheart', 'Gioia mia', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/7N4QlTDnw0NfF9B6kKfG1O9zU35.jpg', 'https://image.tmdb.org/t/p/original/ccQ9abrYHA0aDmaZGqZ1zDaaUem.jpg', 'A reluctant summer together transforms into an enchanting adventure when a young boy discovers his aunt''s mysterious Sicilian house holds secrets and, perhaps, ancient spirits lurking within its walls.', NULL, NULL, 3.4561, 6.6, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11452, 854317, 'tt15119666', NULL, 'Atlantide', 'Atlantide', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/yhcNnMrZB46rvsWFwvGQxNaMIFO.jpg', 'https://image.tmdb.org/t/p/original/eorealYkMv2aUSpz116zLIRa958.jpg', 'Daniele is a young man from Sant’Erasmo, an island on the edges of the Venice Lagoon. He lives on his wits, isolated even from his peer group who are busy exploring an existence of pleasure-seeking expressed in the cult of the barchino (motorboat). This obsession focuses on the building of ever more powerful engines to transform the little lagoon launches into dangerously fast racing boats. Daniele too dreams of a record-breaking barchino, one that will take him to the top of the leader board, but everything he does to further his dream and win respect from the others turns out to be tragically counterproductive. The decline that erodes the relationships, environment and habits of a rootless generation is observed from the timeless perspective of the Venetian landscape and its island outskirts: the point of no return is a foolish, vestigial tale of male initiation. Violent and destined to fail, it explodes dragging the ghost city along on a psychedelic shipwreck.', NULL, NULL, 1.7091, 7.3, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11453, 958192, 'tt14981626', NULL, 'Alma Viva', 'Alma Viva', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/tf5d4OWsKoftpyO1Xp07khxE5nn.jpg', 'https://image.tmdb.org/t/p/original/vqBR5UIMBE2ET2DWpvpDvw5iAsX.jpg', 'Like every summer, little Salomé returns to her family village nestled in the Portuguese mountains for the holidays. As the vacations begin in a carefree atmosphere, her beloved grandmother suddenly dies. While the adults are tearing each other apart over the funeral, Salomé is haunted by the spirit of the one who was considered a witch.', NULL, NULL, 1.0077, 6.019, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11454, 1116242, 'tt27728178', NULL, 'The Red Sea Makes Me Wanna Cry', 'البحر الأحمر يبكي', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/nl4g8vfv9MjIQ8i2cJziJ8z98Ea.jpg', 'https://image.tmdb.org/t/p/original/2LYbxanVHX0WOSnwMSi3WbMPkjN.jpg', 'A haunted woman named Ida journeys from Germany to Jordan, to an eerie and deserted port town on the Red Sea where her partner, Ismail, recently disappeared. Wandering through desolate bars, hotels, and offices, Ida attempts to feel Ismail’s presence one last time and to say goodbye.', NULL, NULL, 0.8287, 6.2, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
