INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11466, NULL, NULL, 1036, 'The Legend of Zelda: Twilight Princess', 'The Legend of Zelda: Twilight Princess', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mtv.jpg', NULL, 'The Legend of Zelda: Twilight Princess is the last Zelda game for GameCube, it was highly anticipated by many members of the gaming community and was regarded as finally fulfilling the dreams of those who wanted a much more realistic and mature game than the ones before. The art is similar to the naturalistic style of Ocarina of Time, rather than the cel-shaded look of The Wind Waker. The main adventure takes place in several provinces with dungeons and temples. New to this game is the ability for Link to transform into a Wolf when entering the Twilight. As a wolf, Link can use his senses to solve puzzles and get past obstacles, he can also dig holes to find hearts and rupees. Twilight Princess has received universal acclaim from reviewers and journalists, who cited it as the greatest Zelda game of all time.', 'https://www.igdb.com/games/the-legend-of-zelda-twilight-princess', '["Nintendo GameCube"]', NULL, NULL, 0, 4.51, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
