INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11526, 70707, 'tt12213652', NULL, 'Bunkers Brutalism and Bloodymindedness', 'Bunkers Brutalism and Bloodymindedness', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/4yXYZafjpm01sEPhaC7No80yRSa.jpg', 'https://image.tmdb.org/t/p/original/c4macr0H9UTlcsXGp92nNVP6w9J.jpg', 'Two-part documentary in which Jonathan Meades makes the case for 20th-century concrete Brutalist architecture in an homage to a style that he sees a brave, bold and bloodyminded.

Tracing its precursors to the once-hated Victorian edifices described as Modern Gothic and before that to the unapologetic baroque visions created by John Vanbrugh, as well as the martial architecture of World War II, Meades celebrates the emergence of the Brutalist spirit in his usual provocative and incisive style.

Never pulling his punches, Meades praises a moment in architecture he considers sublime and decries its detractors.', NULL, NULL, 1.1829, 0.0, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
