INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11581, 515384, 'tt0406506', NULL, 'AM/PM', 'AM/PM', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/oraNKpb3qT6PLEgJUsbHj99Ojce.jpg', NULL, 'Taking its title from an all-day/all-night convenience store, “AM/PM” examines the famous Las Vegas Strip, portraying the disorienting world of corporate hotels and casinos which utilise and redefine the spectacle in relation to architecture. “AM/PM” posits the concept of distraction itself as a strategy and the city as a conspiracy, which manipulates and directs the visitor.', NULL, NULL, 1.0224, 7.0, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
