INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11583, 568124, 'tt2953050', NULL, 'Encanto', 'Encanto', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', 'https://image.tmdb.org/t/p/original/3G1Q5xF40HkUBJXxt2DQgQzKTp5.jpg', 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family''s last hope.', NULL, NULL, 19.9473, 7.566, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11584, 61411, 'tt0064158', NULL, 'Che!', 'Che!', 'movie', 1969, 'https://image.tmdb.org/t/p/w500/hNPbpo2ar8RFu4VX5ZpZ681WMnp.jpg', 'https://image.tmdb.org/t/p/original/8EnsG66fkYFN2UvwhUSwzYCXbNW.jpg', 'Biography of Argentinian revolutionary Ernesto "Che" Guevara, who helped Fidel Castro in his struggle against the corrupt Batista regime, eventually resulting in the overthrow of that government and Castro''s taking over of Cuba. The film covers Guevara''s life from when he first landed in Cuba in 1956 to his death in an ambush by government troops in the mountains of Bolivia in 1967.', NULL, NULL, 1.7731, 4.8, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
