INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11586, 1048225, NULL, NULL, 'Tales of the Bizarre: 2022 Fall Special', '世にも奇妙な物語 ''22秋の特別編', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/jUYZpCHpgiXNTy2mJAYF4rQOkwB.jpg', 'https://image.tmdb.org/t/p/original/ht1Bi2fdQqfUtQ4pYwKjHssUbf6.jpg', 'As part of the long-running anthology series, which began in 1990, this special features a collection of mysterious and thought-provoking stories. Episode Summaries:  1. "Love Triangle with My Ex"  Mika''s ex-boyfriend reappears in her life as a robot, complicating her current relationship.  2. "The Concierge"  A single mother moves into a new apartment where a mysterious concierge begins to fulfill her every wish with unsettling consequences.  3. "Waga-sama"  A workaholic CEO returns to his hometown and encounters a strange boy tied to his childhood and eerie events.  4. "Wait a Minute!"  A man’s love confession is interrupted by two versions of his crush from the future, causing chaos.', NULL, NULL, 0.9819, 6.5, 0, 1.02, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11587, 705581, 'tt11024362', NULL, 'West By North', 'West By North', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/760VjPlVaSIu7EaidxzvEG4mHjy.jpg', NULL, '"The direction of Western Culture''s advance has been WXN, and now no further planetary geography remains into which to penetrate. Today there is talk of heading to Mars - a benighted concept. The geography that remains lies within, but our extroverted society seems largely determined not to explore it. So in a dream I heard the words, ''Flying low, out of creation, they met some rough spots in the mountains.'' The film, in five short sections, explores and expands upon this statement. Beyond that, I would need to write pages. Better to just say, ''Take a look.''" —Abbott Meader', NULL, NULL, 0.3459, 0.0, 0, 1.01, '2026-08-23 01:42:21', '2026-08-23 01:42:21');
