UPDATE "recommendations" SET "tmdb_id"=19908, "imdb_id"='tt1156398', "igdb_id"=NULL, "title"='Zombieland', "original_title"='Zombieland', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oihWVx3imvRKujnGmSDYhfG1gI5.jpg', "overview"='Columbus has made a habit of running from what scares him. Tallahassee doesn''t have fears. If he did, he''d kick their ever-living ass. In a world overrun by zombies, these two are perfectly evolved survivors. But now, they''re about to stare down the most terrifying prospect of all: each other.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.5474, "vote_average"=7.26, "is_ambiguous"=0, "evidence_score"=1.6259333333333334e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=294;
