UPDATE "recommendations" SET "tmdb_id"=639, "imdb_id"='tt0098635', "igdb_id"=NULL, "title"='When Harry Met Sally...', "original_title"='When Harry Met Sally...', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/i8aIbji5vcPoHwcLBZYQSniGkAI.jpg', "overview"='Sex always gets in the way of friendships between men and women. At least, that''s what Harry Burns believes. So when Harry meets Sally Albright and a deep friendship blossoms between them, Harry''s determined not to let his attraction to Sally destroy it. But when a night of weakness ends in a morning of panic, can the pair avoid succumbing to Harry''s fears by remaining friends and admitting they just might be the perfect match for each other?', "external_url"=NULL, "platforms"=NULL, "popularity"=6.211, "vote_average"=7.406, "is_ambiguous"=0, "evidence_score"=2.78325000000000031e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=297;
