UPDATE "recommendations" SET "tmdb_id"=27205, "imdb_id"='tt1375666', "igdb_id"=NULL, "title"='Inception', "original_title"='Inception', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', "overview"='Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', "external_url"=NULL, "platforms"=NULL, "popularity"=64.69, "vote_average"=8.372, "is_ambiguous"=0, "evidence_score"=2.76758333333333332e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=304;
