UPDATE "recommendations" SET "tmdb_id"=841, "imdb_id"='tt0087182', "igdb_id"=NULL, "title"='Dune', "original_title"='Dune', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/4kJmUCE7mkVJjXa7A0g2rY4IGTm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5wJ2tckpvwcxGCAgZiccodwEJpf.jpg', "overview"='In the year 10,191, the most precious substance in the universe is the spice Melange. The spice extends life. The spice expands consciousness. The spice is vital to space travel.  The spice exists on only one planet in the entire universe, the vast desert planet Arrakis, also known as Dune.  Its native inhabitants, the Fremen, have long held a prophecy that a man would come, a messiah who would lead them to true freedom.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.6554, "vote_average"=6.186, "is_ambiguous"=0, "evidence_score"=2.2636842105263156e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=821;
