UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=484, "title"='Silent Hill: Origins', "original_title"='Silent Hill: Origins', "media_type"='game', "release_year"=2007, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyq.jpg', "backdrop_url"=NULL, "overview"='Silent Hill: Origins is the fifth installment in the Silent Hill survival horror series, and a prequel to the original game. As in the previous entries, the player move back and forth between nightmare and real versions of the town, gathering items used to solve puzzles and open up new areas. Monsters of various types provide obstacles and, in series tradition, are mostly disturbingly twisted versions of humanity. The main character can fight with his bare fists or use melee weapons. Unlike previous games in the series, melee weapons break after a time. There are also one-shot items that can be thrown and several guns. There is no HUD, but the edge of the screen turns red when the protagonist is near death.', "external_url"='https://www.igdb.com/games/silent-hill-origins', "platforms"='["PlayStation Portable", "PlayStation 2"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=16.25, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=838;
