UPDATE "recommendations" SET "tmdb_id"=667216, "imdb_id"='tt10365998', "igdb_id"=NULL, "title"='Infinity Pool', "original_title"='Infinity Pool', "media_type"='movie', "release_year"=2023, "poster_url"='https://image.tmdb.org/t/p/w500/cQKyNm0Nz6KWiDBQF9w4aZAmOfC.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1xhcEecvRJXQ2OAVO7l9btlrN6D.jpg', "overview"='While staying at an isolated island resort, James and Em are enjoying a perfect vacation of pristine beaches, exceptional staff, and soaking up the sun. But guided by the seductive and mysterious Gabi, they venture outside the resort grounds and find themselves in a culture filled with violence, hedonism, and untold horror. A tragic accident leaves them facing a zero tolerance policy for crime: either you''ll be executed, or, if you’re rich enough to afford it, you can watch yourself die instead.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.7805, "vote_average"=6.049, "is_ambiguous"=0, "evidence_score"=2.22631578947368424e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=1192;
