UPDATE "recommendations" SET "tmdb_id"=14239, "imdb_id"='tt0104009', "igdb_id"=NULL, "title"='Cool World', "original_title"='Cool World', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/mqzRUHNtFwmgJCmSnvq3JnX0xgZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uRUAwzXOU75vmO0CD1RzY0CaZ8d.jpg', "overview"='While incarcerated for murder, cartoonist Jack Deebs found escape by creating Cool World, a series featuring a voluptuous femme fatale named Holli Would. But the artist becomes a prisoner of his own fantasies when Holli transports Jack into Cool World with a scheme to seduce him and bring herself to life. Hard-boiled detective Frank Harris – the only other human in Cool World – cautions Jack with the law: Noids (humans) don''t have sex with doodles (cartoons). However, flesh proves weaker than ink as Holli takes human form in Las Vegas, staring in a trans-universal chase that threatens the destruction of both worlds.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5493, "vote_average"=5.655, "is_ambiguous"=0, "evidence_score"=20.536875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=1238;
