UPDATE "recommendations" SET "tmdb_id"=47665, "imdb_id"='tt2375692', "igdb_id"=NULL, "title"='Black Sails', "original_title"='Black Sails', "media_type"='tv', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/mZcSwrDdw6cdOVgXm496DgwrQcQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/A7lo83g09i3cDmLRKtDiiYN8w0z.jpg', "overview"='The pirate adventures of Captain Flint and his men twenty years prior to Robert Louis Stevenson’s classic “Treasure Island.” Flint, the most brilliant and most feared pirate captain of his day, takes on a fast-talking young addition to his crew who goes by the name John Silver. Threatened with extinction on all sides, they fight for the survival of New Providence Island, the most notorious criminal haven of its day – a debauched paradise teeming with pirates, prostitutes, thieves and fortune seekers, a place defined by both its enlightened ideals and its stunning brutality.', "external_url"=NULL, "platforms"=NULL, "popularity"=29.5915, "vote_average"=7.623, "is_ambiguous"=0, "evidence_score"=16.7, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=1759;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=62, "title"='The Curse of Monkey Island', "original_title"='The Curse of Monkey Island', "media_type"='game', "release_year"=1997, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co30yu.jpg', "backdrop_url"=NULL, "overview"='The Curse of Monkey Island is the third installment in the Monkey Island adventure game series. Players control Guybrush Threepwood, a aspiring pirate, as he navigates the Caribbean to save his love Elaine from a curse that turned her into a golden statue. The game features hand-drawn cartoon graphics, voice acting, and the series'' trademark humor and puzzle-solving gameplay. Guybrush must outwit a cast of colorful characters, including the ghostly pirate LeChuck, while exploring various islands and engaging in pirate-themed challenges. The point-and-click interface allows players to interact with the environment, collect items, and solve puzzles to progress through the story. With its blend of comedy, swashbuckling adventure, and clever puzzles, The Curse of Monkey Island continues the series'' tradition of witty, engaging storytelling in a pirate-themed setting.', "external_url"='https://www.igdb.com/games/the-curse-of-monkey-island', "platforms"='["PC (Microsoft Windows)", "Mac"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=11.03, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-23 01:42:21' WHERE "id"=1761;
