UPDATE "recommendations" SET "tmdb_id"=2163, "imdb_id"='tt0118771', "igdb_id"=NULL, "title"='Breakdown', "original_title"='Breakdown', "media_type"='movie', "release_year"=1997, "poster_url"='https://image.tmdb.org/t/p/w500/m3VB59ppr1RlpxNUYRUfZTgjgU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/e86x1nXqfXRlqATuy60MmzFUFQr.jpg', "overview"='On their cross-country drive, a married couple, Jeff and Amy Taylor, experience car trouble after their SUV breaks down. Stranded in the New Mexico desert, the two catch a break when a passing truck driver offers Amy a ride to a nearby café to call for help. Meanwhile, Jeff is able to fix the car and make his way to the café, but Amy isn''t there. He tracks down the trucker ― who tells the police he''s never seen Jeff or his wife before. Jeff then begins a desperate, frenzied search for Amy.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.7622, "vote_average"=6.934, "is_ambiguous"=0, "evidence_score"=2.03173333333333339e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-23 01:42:21' WHERE "id"=3219;
