UPDATE "recommendations" SET "tmdb_id"=6878, "imdb_id"='tt0107131', "igdb_id"=NULL, "title"='Homeward Bound: The Incredible Journey', "original_title"='Homeward Bound: The Incredible Journey', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/el6dJEpK97OJRQiQhuiSGk2jkV5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xDwDhLtQnA7jK4f7DVkdeSvZnAp.jpg', "overview"='Before the Seavers leave for a family vacation to San Francisco, they drop off their pets -- Chance, an adventurous American bulldog; Shadow, a wise golden retriever; and Sassy, a cautious cat -- at a friend''s ranch. But when the animals start to worry that they''ve been left for good, the three embark together on a treacherous and thrilling journey to find their way back home through the California wilderness.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6272, "vote_average"=6.992, "is_ambiguous"=0, "evidence_score"=2.24088888888888888e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-23 01:42:21' WHERE "id"=3312;
UPDATE "recommendations" SET "tmdb_id"=62204, "imdb_id"='tt0082484', "igdb_id"=NULL, "title"='Quest for Fire', "original_title"='La Guerre du feu', "media_type"='movie', "release_year"=1981, "poster_url"='https://image.tmdb.org/t/p/w500/tyzW1M00xfHKNtmTlT6wJ3F4pNr.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5l3Xb2WQR0nXiVhbj5rAv0z4xsZ.jpg', "overview"='In the prehistoric world, a Cro-Magnon tribe depends on an ever-burning source of fire, which eventually extinguishes. Lacking the knowledge to start a new fire, the tribe sends three warriors on a quest for more. With the tribe''s future at stake, the warriors make their way across a treacherous landscape full of hostile tribes and monstrous beasts. On their journey, they encounter Ika, a woman who has the knowledge they seek.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.9448, "vote_average"=7.036, "is_ambiguous"=0, "evidence_score"=8.13, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-23 01:42:21' WHERE "id"=3317;
