UPDATE "recommendations" SET "tmdb_id"=10376, "imdb_id"='tt0120731', "igdb_id"=NULL, "title"='The Legend of 1900', "original_title"='La leggenda del pianista sull''oceano', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/muSeX7fnNw0pv4zHK7RSwZln6Hk.jpg', "overview"='Musician Max Tooney goes to sell his prized Conn trumpet to a music shop, where he plays the instrument one last time. The shopkeeper recognises the song as one on a record matrix he found and asks who the piece is by. Tooney tells the story of an infant found abandoned in the first class dining room of the four-stacker ocean-liner SS Virginian on 1 January 1900. Danny Boodman, a coal-man from the boiler room, names the boy Danny Boodman T. D. Lemon 1900, after himself, the fruit crate the boy was found in, and the year, and raises him as his own.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.7183, "vote_average"=8.24, "is_ambiguous"=0, "evidence_score"=6.00666666666666682e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-23 01:42:21' WHERE "id"=3350;
