UPDATE "recommendations" SET "tmdb_id"=11286, "imdb_id"='tt0082136', "igdb_id"=NULL, "title"='The Cannonball Run', "original_title"='The Cannonball Run', "media_type"='movie', "release_year"=1981, "poster_url"='https://image.tmdb.org/t/p/w500/pvn9SbMq9q8wJXt3KAp9kP7pmpb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6Jw1a3ctW5eQjonmPCwPrOeYVNN.jpg', "overview"='A cross-country road race is based on an actual event, the Cannonball Baker Sea to Shining Sea Memorial Trophy Dash, organized by Brock Yates to protest the 55 mph speed limit then in effect in the U.S. The Cannonball was named for Erwin G. "Cannonball" Baker, who in the roaring 20''s rode his motorcycle across the country. Many of the characters are based on ruses developed by real Cannonball racers over the several years that the event was run.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6913, "vote_average"=6.159, "is_ambiguous"=0, "evidence_score"=6.316, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-23 01:42:21' WHERE "id"=5439;
