UPDATE "recommendations" SET "tmdb_id"=15477, "imdb_id"='tt0110395', "igdb_id"=NULL, "title"='Love and a .45', "original_title"='Love and a .45', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/xz7rXuL1lkc6tkt1rS0N05rxtRX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5edOoD7mdBrHm2LWeZQIQHiFOrF.jpg', "overview"='Small-time criminal Watty Watts attempts to rob a convenience store with his drug-addict buddy, Billy Mack Black. The robbery, however, leads to murder, and soon Watty leaves Billy behind and goes on the run with his beloved girlfriend, Starlene. Heading toward Mexico, the fugitive couple gets plenty of media coverage, until there are even more people on their trail. Can Watty and Starlene make it south of the border without getting caught?', "external_url"=NULL, "platforms"=NULL, "popularity"=0.926, "vote_average"=5.757, "is_ambiguous"=0, "evidence_score"=6.3, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-23 01:42:21' WHERE "id"=5443;
