UPDATE "recommendations" SET "tmdb_id"=23514, "imdb_id"='tt0376136', "igdb_id"=NULL, "title"='The Rum Diary', "original_title"='The Rum Diary', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/uErFROiMrpk7owQWKK3bpD4hSJs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jxsWn2D4pk0rgtO3hBzFq9rROZ8.jpg', "overview"='Tired of the noise and madness of New York and the crushing conventions of late Eisenhower-era America, itinerant journalist Paul Kemp travels to the pristine island of Puerto Rico to write for a local San Juan newspaper run by the downtrodden editor Lotterman. Adopting the rum-soaked lifestyle of the late ‘50s version of Hemingway’s ''The Lost Generation'', Paul soon becomes entangled with a very attractive American woman and her fiancée, a businessman involved in shady property development deals.  It is within this world that Kemp ultimately discovers his true voice as a writer and integrity as a man.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.2624, "vote_average"=5.883, "is_ambiguous"=0, "evidence_score"=11.70875, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-23 01:42:21' WHERE "id"=5825;
