UPDATE "recommendations" SET "tmdb_id"=8326, "imdb_id"='tt0311289', "igdb_id"=NULL, "title"='Holes', "original_title"='Holes', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/o2Dm2mcE1qW8vT0bpsJO5OMBbqa.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cVMK2k0Wbs8DV3IK5sS4ziVenrI.jpg', "overview"='After being wrongfully convicted for stealing a pair of shoes, Stanley Yelnats is sent away to Camp Green Lake, a boys detention facility where inmates are forced to dig holes all day in the hot desert sun as a form of character building. As he endures the brutal routine, Stanley begins to uncover a hidden truth behind the camp—one that connects to a dangerous secret and his family’s history.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8149, "vote_average"=6.901, "is_ambiguous"=0, "evidence_score"=17.545, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-23 01:42:21' WHERE "id"=8655;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=2155, "title"='Dark Souls', "original_title"='Dark Souls', "media_type"='game', "release_year"=2011, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1x78.jpg', "backdrop_url"=NULL, "overview"='Dark Souls is an action role-playing game developed by FromSoftware and published by Bandai Namco Entertainment. Released in September 2011 as a spiritual sequel to Demon''s Souls, it is set in a dark, medieval fantasy world. It is renowned for its challenging gameplay, intricate level design, and deep lore. Players control a customizable character known as the Chosen Undead, embarking on a perilous journey to uncover the secrets of the cursed land of Lordran.

Dark Souls is known for its punishing difficulty, requiring players to carefully manage combat, stamina, and resources while navigating hostile environments filled with dangerous enemies and formidable bosses. The game features a unique multiplayer component, allowing players to leave messages for others, summon allies for cooperative play, or invade other players'' worlds for PvP combat.

The original release of Dark Souls received critical acclaim for its atmospheric world, innovative mechanics, and rewarding gameplay, solidifying its place as a seminal title in the action RPG genre.', "external_url"='https://www.igdb.com/games/dark-souls', "platforms"='["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=4.72666666666666657e+00, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-23 01:42:21' WHERE "id"=8692;
