UPDATE "recommendations" SET "tmdb_id"=49530, "imdb_id"='tt1637688', "igdb_id"=NULL, "title"='In Time', "original_title"='In Time', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pxL08w7Eq0vKrQ3mJzYp0VHGaKG.jpg', "overview"='In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the "time keepers".', "external_url"=NULL, "platforms"=NULL, "popularity"=13.8073, "vote_average"=6.972, "is_ambiguous"=0, "evidence_score"=6.36333333333333328e+00, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-23 01:42:21' WHERE "id"=9582;
UPDATE "recommendations" SET "tmdb_id"=9059, "imdb_id"='tt0114608', "igdb_id"=NULL, "title"='Tales from the Crypt: Demon Knight', "original_title"='Tales from the Crypt: Demon Knight', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/8uD5yk0ECebJ59lhvhTBKhUojc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/47WfbtmsreEhNy2OzEDBxk9ZlzG.jpg', "overview"='Ex-soldier Frank Brayker is the guardian of an ancient key that can unlock tremendous evil; the sinister Collector is a demon who wants the key so he can initiate the apocalypse. On the run from wicked mercenaries for almost 90 years, Brayker finally stops in at a boarding house in New Mexico where — with the help of its residents — he plans to face off against the Collector and his band of ghouls, preventing them from ever seizing the key.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6445, "vote_average"=6.845, "is_ambiguous"=0, "evidence_score"=5.025, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-23 01:42:21' WHERE "id"=9600;
UPDATE "recommendations" SET "tmdb_id"=94329, "imdb_id"='tt1899353', "igdb_id"=NULL, "title"='The Raid', "original_title"='Serbuan Maut', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3wf5wV222vqTmz10y1vbrPgrGDf.jpg', "overview"='Deep in the heart of Jakarta''s slums lies an impenetrable safe house for the world''s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building''s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city''s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.5349, "vote_average"=7.407, "is_ambiguous"=0, "evidence_score"=8.85000000000000142e+00, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-23 01:42:21' WHERE "id"=9635;
