UPDATE "recommendations" SET "tmdb_id"=829732, "imdb_id"='tt10106394', "igdb_id"=NULL, "title"='Forest for the Trees', "original_title"='Forest for the Trees', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/4goHo1mCrKMj39wMJvVs9g1Lo3i.jpg', "backdrop_url"=NULL, "overview"='Award-winning war photographer Rita Leistner goes back to her roots as a tree planter in the wilderness of British Columbia, offering an inside take on the grueling, sometimes fun and always life-changing experience of restoring Canada’s forests. Leistner, who has photographed some of the world’s most dangerous places, credits the challenge of tree-planting for her physical and mental endurance. In Forest for the Trees, her first feature film, she revisits her past to share the lessons she learned. The film introduces us to everyday life on the “cut-block” and the brave souls who fight through rough terrains and work endless hours to bring our forests to life. The rugged BC landscape comes to life magically in Leistner’s photography, while the quirky characters and nuggets of wisdom shared around the campfire tell a sincere story of community.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9832, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=10.01, "created_at"='2026-08-12 02:31:31', "updated_at"='2026-08-23 01:42:21' WHERE "id"=9892;
