UPDATE "recommendations" SET "tmdb_id"=14537, "imdb_id"='tt0056058', "igdb_id"=NULL, "title"='Harakiri', "original_title"='切腹', "media_type"='movie', "release_year"=1962, "poster_url"='https://image.tmdb.org/t/p/w500/zK7HsOC7QxW1ldKIeFG8YJ5F2Eb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nC3IjYhUgZWgfKfFX0ygMigFwgc.jpg', "overview"='Down-on-his-luck veteran Tsugumo Hanshirō enters the courtyard of the prosperous House of Iyi. Unemployed, and with no family, he hopes to find a place to commit seppuku—and a worthy second to deliver the coup de grâce in his suicide ritual. The senior counselor for the Iyi clan questions the ronin’s resolve and integrity, suspecting Hanshirō of seeking charity rather than an honorable end. What follows is a pair of interlocking stories which lay bare the difference between honor and respect, and promises to examine the legendary foundations of the Samurai code.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.5031, "vote_average"=8.454, "is_ambiguous"=0, "evidence_score"=1.01833333333333335e+01, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-23 01:42:21' WHERE "id"=10999;
UPDATE "recommendations" SET "tmdb_id"=74726, "imdb_id"='tt1838571', "igdb_id"=NULL, "title"='Juan of the Dead', "original_title"='Juan de los muertos', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/yQLHnDXOdl2gny6glOsts3Btczc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qlKK49jNOK9a3DhDbWKoB8hA5Vn.jpg', "overview"='While Havana is full of zombies hungry for human flesh, official media reported that the disturbances are caused by dissidents paid by the United States. Panic seizes all until Juan comes to the rescue: he discovers he can kill the undead destroying his brain, and decides to start a small business under the slogan "We kill your loved ones."', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9263, "vote_average"=6.236, "is_ambiguous"=0, "evidence_score"=8.68333333333333357e+00, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-23 01:42:21' WHERE "id"=11016;
